    # signal has at least two positions and the padding stays strictly
    # inside one period; PyTorch-style reflection otherwise is undefined.
    if padding_mode == "reflect":
        if N <= 1:
            raise ValueError(
                "reflect padding requires length greater than 1"
            )
        if P >= N:
            raise ValueError(
